{
  "assessments": [
    {
      "proposition_id": "P1",
      "status": "full",
      "summary_quote": "This bill proposes to increase the amount for teachers' supplies in Tennessee Code Annotated Section 49-3-359(a) from $200 to $500.",
      "rationale": "Identifies the amended subsection and accurately conveys the replacement of $200 with $500."
    },
    {
      "proposition_id": "P2",
      "status": "partial",
      "summary_quote": "The bill states that it is not an appropriation of funds, meaning money cannot be spent unless it is specifically appropriated by the General Appropriations Act.",
      "rationale": "Conveys that the act does not appropriate funds and that spending requires a specific General Appropriations Act appropriation, but omits the separate prohibition on obligating funds without that appropriation."
    },
    {
      "proposition_id": "P3",
      "status": "full",
      "summary_quote": "If passed, this change would take effect on July 1, 2025.",
      "rationale": "Accurately states the act's effective date."
    }
  ]
}
